// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Private_Bank} from "../src/Private_Bank.sol";

contract InvMutTest is Test {
    Private_Bank c;
    function setUp() public { c = new Private_Bank(address(this)); }
    function testRegression_property() public {
        vm.deal(address(this), 1 ether);

        address caller = address(0x1234);
        vm.deal(caller, 0.5 ether);

        vm.prank(caller);
        c.Deposit{value: 0.5 ether}();

        vm.prank(caller);
        c.CashOut(0.5 ether);

        assertTrue(c.MinDeposit() == 1 ether, "Reference MinDeposit should be 1 ether");
    }
}
